	    Insurer entity = new Insurer();
            entity.setInsurerId( event.getInsurerId() );
            entity.setName( event.getName() );
            entity.setLegalName( event.getLegalName() );
            entity.setDomicileCountry( event.getDomicileCountry() );
            entity.setNaicNumber( event.getNaicNumber() );
            entity.setWebsite( event.getWebsite() );
	    
    	// ------------------------------------------
