    /**
     * Method to retrieve the Insurer via an InsurerPrimaryKey.
     * @param 	id Long
     * @return 	Insurer
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Insurer handle( FindInsurerQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getInsurerId() );
    }
    
    /**
     * Method to retrieve a collection of all Insurers
     *
     * @param	query	FindAllInsurerQuery 
     * @return 	List<Insurer> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Insurer> handle( FindAllInsurerQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindInsurer,
 * but only if the id matches
 *
 * @param		entity	Insurer
 */
	protected void emitFindInsurer( Insurer entity ) {
		LOGGER.info("handling emitFindInsurer" );
		
	    queryUpdateEmitter.emit(FindInsurerQuery.class,
	                            query -> query.getFilter().getInsurerId().equals(entity.getInsurerId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllInsurer
	 * 
	 * @param		entity	Insurer
	 */
	protected void emitFindAllInsurer( Insurer entity ) {
		LOGGER.info("handling emitFindAllInsurer" );
		
	    queryUpdateEmitter.emit(FindAllInsurerQuery.class,
	                            query -> true,
	                            entity);
	}

